(function (global) {
    "use strict";
    let serial = 0;
    const chapterCounts = {};
    function q(chapterId, difficulty, en, hi, choices, answer, why, whyHi) {
        serial += 1;
        chapterCounts[chapterId] = (chapterCounts[chapterId] || 0) + 1;
        const offset = (serial - 1) % 4;
        const questionId = "M1-" + String(serial).padStart(3, "0");
        const chapter = global.OLEVEL_CATALOG[0].chapters.find(function (entry) { return entry.id === chapterId; });
        const topicIndex = (chapterCounts[chapterId] - 1) % chapter.topics.length;
        const options = choices.map(function (choice, index) {
            return { id: questionId + "-O" + (index + 1), en: choice[0], hi: choice[1] };
        });
        const orderedChoices = options.slice(offset).concat(options.slice(0, offset));
        return {
            id: questionId,
            moduleId: "M1-R5.1",
            chapterId: chapterId,
            topicId: chapterId + "-topic-" + (topicIndex + 1),
            topic: chapter.topics[topicIndex],
            difficulty: difficulty,
            questionEnglish: en,
            questionHindi: hi,
            options: orderedChoices,
            correctOptionId: options[answer].id,
            explanationEnglish: why,
            explanationHindi: whyHi,
            sourceType: "Original Practice",
            source: { name: "ZeroKB original practice", year: null }
        };
    }
    global.OLEVEL_BANKS = global.OLEVEL_BANKS || {};
    global.OLEVEL_BANKS.m1 = [
        q("computer-fundamentals", "Moderate", "A processor repeatedly needs the same instruction and data. Which storage level usually reduces access latency without replacing main memory?", "प्रोसेसर को एक ही निर्देश और डेटा बार-बार चाहिए। मुख्य मेमोरी का स्थान लिए बिना कौन-सा स्टोरेज सामान्यतः पहुँच विलंब घटाता है?", [["Cache memory near the CPU", "CPU के पास कैश मेमोरी"], ["Optical archive disc", "ऑप्टिकल आर्काइव डिस्क"], ["USB flash drive", "USB फ्लैश ड्राइव"], ["Network printer buffer", "नेटवर्क प्रिंटर बफर"]], 0, "CPU cache keeps frequently used data close to the processor; it is smaller and faster than RAM.", "CPU कैश बार-बार उपयोग होने वाला डेटा प्रोसेसर के पास रखता है; यह RAM से छोटा और तेज़ होता है।"),
        q("computer-fundamentals", "Hard", "A system must transfer data from an input device to memory while the CPU performs another task. Which mechanism can coordinate this transfer with limited CPU involvement?", "CPU के किसी अन्य कार्य के दौरान सिस्टम को इनपुट डिवाइस से मेमोरी में डेटा भेजना है। CPU की कम भागीदारी में इस स्थानांतरण का समन्वय कौन-सा तंत्र कर सकता है?", [["DMA controller", "DMA नियंत्रक"], ["Arithmetic logic unit", "अंकगणितीय तर्क इकाई"], ["Instruction decoder only", "केवल निर्देश डिकोडर"], ["Display adapter palette", "डिस्प्ले एडाप्टर पैलेट"]], 0, "Direct Memory Access coordinates device-memory transfers so the CPU need not copy every byte itself.", "Direct Memory Access डिवाइस और मेमोरी के बीच स्थानांतरण का समन्वय करता है, इसलिए CPU को प्रत्येक बाइट स्वयं कॉपी नहीं करनी पड़ती।"),

        q("operating-system", "Moderate", "Several ready processes share one CPU. Which operating-system function decides which process runs next?", "कई तैयार प्रक्रियाएँ एक CPU साझा करती हैं। अगली बार कौन-सी प्रक्रिया चलेगी, यह ऑपरेटिंग सिस्टम का कौन-सा कार्य तय करता है?", [["CPU scheduling", "CPU शेड्यूलिंग"], ["File compression", "फाइल संपीड़न"], ["Disk formatting", "डिस्क फॉर्मेटिंग"], ["Device calibration", "डिवाइस कैलिब्रेशन"]], 0, "The process scheduler allocates CPU time among ready processes according to a scheduling policy.", "प्रोसेस शेड्यूलर नीति के अनुसार तैयार प्रक्रियाओं के बीच CPU समय आवंटित करता है।"),
        q("operating-system", "Hard", "A running program requests memory beyond the currently available RAM, and the system uses disk space to keep pages. Which mechanism is being used?", "चल रहा प्रोग्राम उपलब्ध RAM से अधिक मेमोरी माँगता है और सिस्टम पेज रखने के लिए डिस्क स्थान का उपयोग करता है। कौन-सा तंत्र उपयोग हो रहा है?", [["Virtual memory with paging", "पेजिंग सहित वर्चुअल मेमोरी"], ["CPU cache mapping", "CPU कैश मैपिंग"], ["File allocation table", "फाइल आवंटन तालिका"], ["Spooling", "स्पूलिंग"]], 0, "Virtual memory maps process address spaces to physical memory and can keep inactive pages on secondary storage.", "वर्चुअल मेमोरी प्रक्रिया के एड्रेस स्पेस को भौतिक मेमोरी से मैप करती है और निष्क्रिय पेज द्वितीयक स्टोरेज पर रख सकती है।"),

        q("word-processing", "Moderate", "A long report needs a consistently formatted table of contents that updates when headings move. What should the author use?", "एक लंबी रिपोर्ट में ऐसा समान रूप से स्वरूपित विषय-सूची चाहिए जो शीर्षकों के बदलने पर अपडेट हो। लेखक को क्या उपयोग करना चाहिए?", [["Heading styles and an automatic table of contents", "Heading styles और स्वचालित विषय-सूची"], ["Manually typed page numbers", "हाथ से टाइप किए गए पृष्ठ नंबर"], ["A text box for every heading", "हर शीर्षक के लिए टेक्स्ट बॉक्स"], ["Repeated spaces and tabs", "बार-बार स्पेस और टैब"]], 0, "Structural heading styles let a word processor identify sections and regenerate the table of contents.", "संरचनात्मक heading styles वर्ड प्रोसेसर को अनुभाग पहचानने और विषय-सूची फिर बनाने देते हैं।"),
        q("word-processing", "Hard", "A school must create individual letters from one template using a spreadsheet of names and addresses. Which feature is designed for this?", "एक स्कूल को नाम और पते वाली स्प्रेडशीट के आधार पर एक टेम्पलेट से अलग-अलग पत्र बनाने हैं। इसके लिए कौन-सी सुविधा बनाई गई है?", [["Mail merge", "मेल मर्ज"], ["Track changes", "ट्रैक चेंजेस"], ["Page break", "पेज ब्रेक"], ["Word count", "वर्ड काउंट"]], 0, "Mail merge combines a main document with data fields to produce personalized copies.", "मेल मर्ज मुख्य दस्तावेज़ को डेटा फ़ील्ड से जोड़कर व्यक्तिगत प्रतियाँ बनाता है।"),

        q("spreadsheet", "Moderate", "Cell D5 contains =B5*$C$2. When this formula is copied down one row, which reference behavior is expected?", "सेल D5 में =B5*$C$2 है। इस सूत्र को एक पंक्ति नीचे कॉपी करने पर कौन-सा संदर्भ व्यवहार अपेक्षित है?", [["B5 becomes B6 while $C$2 stays fixed", "B5, B6 बनेगा जबकि $C$2 स्थिर रहेगा"], ["Both references stay fixed", "दोनों संदर्भ स्थिर रहेंगे"], ["Both references shift to row 6", "दोनों संदर्भ पंक्ति 6 पर खिसकेंगे"], ["The formula becomes a text value", "सूत्र टेक्स्ट मान बन जाएगा"]], 0, "B5 is relative and adjusts during copying; $C$2 is absolute and remains fixed.", "B5 सापेक्ष संदर्भ है और कॉपी करते समय बदलता है; $C$2 निरपेक्ष है और स्थिर रहता है।"),
        q("spreadsheet", "Hard", "A worksheet must count records in C2:C200 only when the value in B is \"Paid\" and the value in C exceeds 500. Which function pattern fits?", "वर्कशीट में C2:C200 के रिकॉर्ड तभी गिनने हैं जब B का मान \"Paid\" हो और C का मान 500 से अधिक हो। कौन-सा फ़ंक्शन उपयुक्त है?", [["COUNTIFS with both criteria ranges", "दोनों criteria ranges के साथ COUNTIFS"], ["SUM with one criterion", "एक criterion के साथ SUM"], ["AVERAGE on column B", "कॉलम B पर AVERAGE"], ["CONCAT on both columns", "दोनों कॉलम पर CONCAT"]], 0, "COUNTIFS counts rows only when all supplied range-and-criterion pairs are satisfied.", "COUNTIFS उन पंक्तियों को गिनता है जहाँ दिए गए सभी range और criterion जोड़े पूरे हों।"),

        q("presentation", "Moderate", "A presentation's logo and footer should appear in the same position on every slide. Where is the most maintainable place to set them?", "प्रस्तुति का लोगो और फुटर हर स्लाइड पर एक ही स्थान पर दिखना चाहिए। इन्हें सेट करने का सबसे रखरखाव-योग्य स्थान कौन-सा है?", [["Slide master or theme layout", "स्लाइड मास्टर या थीम लेआउट"], ["A separate manually placed copy on each slide", "हर स्लाइड पर अलग से हाथ से रखी गई प्रति"], ["Speaker notes", "स्पीकर नोट्स"], ["The animation pane", "एनिमेशन पेन"]], 0, "Master layouts apply shared design elements consistently and allow a single-point update.", "मास्टर लेआउट साझा डिज़ाइन तत्वों को समान रूप से लागू करते हैं और एक ही स्थान से अपडेट करने देते हैं।"),
        q("presentation", "Hard", "A chart must reflect updated spreadsheet figures whenever its source data changes. What should be used when supported by the authoring tools?", "स्रोत डेटा बदलने पर चार्ट में स्प्रेडशीट के नए आँकड़े दिखने चाहिए। उपलब्ध हो तो किसका उपयोग करना चाहिए?", [["A linked chart with a maintained data source", "डेटा स्रोत से जुड़ा हुआ चार्ट"], ["A screenshot of the chart", "चार्ट का स्क्रीनशॉट"], ["A flattened image pasted from a slide", "स्लाइड से चिपकाई गई सपाट इमेज"], ["A manually redrawn shape", "हाथ से बनाया गया आकार"]], 0, "A linked chart can refresh from its source data; a screenshot or flattened image cannot update its values.", "लिंक किया गया चार्ट स्रोत डेटा से अपडेट हो सकता है; स्क्रीनशॉट या सपाट इमेज के मान अपडेट नहीं होते।"),

        q("internet-www", "Moderate", "A user enters a domain name in a browser. Which service normally helps resolve that name to an IP address?", "उपयोगकर्ता ब्राउज़र में डोमेन नाम दर्ज करता है। उस नाम को IP पते में बदलने में सामान्यतः कौन-सी सेवा मदद करती है?", [["DNS", "DNS"], ["DHCP", "DHCP"], ["SMTP", "SMTP"], ["NTP", "NTP"]], 0, "DNS translates domain names into the address information needed to contact internet hosts.", "DNS डोमेन नामों को इंटरनेट होस्ट से संपर्क के लिए आवश्यक एड्रेस जानकारी में बदलता है।"),
        q("internet-www", "Hard", "A browser shows HTTPS and a valid certificate, but a user must still decide whether to trust a page asking for payment details. What is the best interpretation?", "ब्राउज़र में HTTPS और वैध प्रमाणपत्र दिखता है, फिर भी भुगतान विवरण माँगने वाले पेज पर भरोसा करना है या नहीं, यह उपयोगकर्ता को तय करना है। सही निष्कर्ष क्या है?", [["The connection is encrypted, but the certificate alone does not prove the site's business is trustworthy", "कनेक्शन एन्क्रिप्ट है, पर प्रमाणपत्र अकेले साइट के व्यवसाय को विश्वसनीय सिद्ध नहीं करता"], ["HTTPS guarantees the seller will deliver goods", "HTTPS गारंटी देता है कि विक्रेता सामान पहुँचाएगा"], ["The certificate confirms the site's content is accurate", "प्रमाणपत्र साइट की सामग्री को सही प्रमाणित करता है"], ["HTTPS prevents every form of phishing", "HTTPS हर प्रकार की फ़िशिंग रोकता है"]], 0, "HTTPS protects the connection and authenticates a domain under certificate rules; it is not a guarantee of honest content.", "HTTPS कनेक्शन की रक्षा करता है और प्रमाणपत्र नियमों के अनुसार डोमेन की पहचान करता है; यह ईमानदार सामग्री की गारंटी नहीं है।"),

        q("email-egovernance", "Moderate", "A message says an account will close today and asks the recipient to sign in through an unfamiliar link. Which response is safest?", "एक संदेश कहता है कि खाता आज बंद हो जाएगा और किसी अपरिचित लिंक से साइन इन करने को कहता है। सबसे सुरक्षित प्रतिक्रिया क्या है?", [["Open the official service independently and check the account there", "आधिकारिक सेवा को अलग से खोलकर वहीं खाते की जाँच करें"], ["Reply with the password to verify identity", "पहचान सत्यापित करने के लिए पासवर्ड से जवाब दें"], ["Forward the link to colleagues to test it", "लिंक जाँचने के लिए सहकर्मियों को भेजें"], ["Enter details quickly before the deadline", "समय-सीमा से पहले जल्दी से विवरण भरें"]], 0, "Urgency and an unfamiliar login link are phishing indicators; navigate independently to the known official service.", "तत्काल दबाव और अपरिचित लॉगिन लिंक फ़िशिंग के संकेत हैं; ज्ञात आधिकारिक सेवा को स्वयं खोलें।"),
        q("email-egovernance", "Hard", "An e-governance portal provides a digitally signed certificate. What can a successfully verified digital signature primarily establish?", "ई-गवर्नेंस पोर्टल डिजिटल रूप से हस्ताक्षरित प्रमाणपत्र देता है। सफलतापूर्वक सत्यापित डिजिटल हस्ताक्षर मुख्यतः क्या स्थापित कर सकता है?", [["Signer authenticity and document integrity", "हस्ताक्षरकर्ता की प्रामाणिकता और दस्तावेज़ की अखंडता"], ["That the document is secret from every reader", "कि दस्तावेज़ हर पाठक से गुप्त है"], ["That the signer agrees with every later edit", "कि हस्ताक्षरकर्ता बाद के हर संपादन से सहमत है"], ["That the computer is free of malware", "कि कंप्यूटर में मैलवेयर नहीं है"]], 0, "Signature verification can establish the signing identity under the trust framework and detect post-signing changes; it does not encrypt by itself.", "हस्ताक्षर सत्यापन विश्वास-ढाँचे के अंतर्गत हस्ताक्षर पहचान स्थापित कर सकता है और बाद के बदलाव पकड़ सकता है; यह स्वयं एन्क्रिप्शन नहीं करता।"),

        q("digital-finance", "Moderate", "A customer scans a merchant's UPI QR code. Which action is essential before approving the payment?", "ग्राहक व्यापारी का UPI QR कोड स्कैन करता है। भुगतान स्वीकृत करने से पहले कौन-सी कार्रवाई आवश्यक है?", [["Verify the payee and amount shown in the payment app", "भुगतान ऐप में दिख रहे प्राप्तकर्ता और राशि की पुष्टि करें"], ["Share the UPI PIN with the merchant", "व्यापारी के साथ UPI PIN साझा करें"], ["Approve any collect request without checking it", "जाँच किए बिना कोई भी collect request स्वीकृत करें"], ["Disable the phone lock", "फोन लॉक बंद करें"]], 0, "Confirm the recipient and amount; the UPI PIN authorizes a debit and must never be shared.", "प्राप्तकर्ता और राशि की पुष्टि करें; UPI PIN डेबिट को अधिकृत करता है और इसे कभी साझा नहीं करना चाहिए।"),
        q("digital-finance", "Hard", "A payer receives an unexpected UPI collect request and is told that entering a PIN will credit a refund. What should the payer understand?", "भुगतानकर्ता को अप्रत्याशित UPI collect request मिलती है और कहा जाता है कि PIN डालने से रिफंड आएगा। उसे क्या समझना चाहिए?", [["Approving with the PIN authorizes a payment/debit, so reject and verify the refund through the official channel", "PIN से स्वीकृति भुगतान/डेबिट अधिकृत करती है; अनुरोध अस्वीकार कर आधिकारिक माध्यम से रिफंड जाँचें"], ["A UPI PIN is only needed to receive money", "पैसा पाने के लिए ही UPI PIN चाहिए"], ["The request is safe because it uses a QR code", "QR कोड होने से अनुरोध सुरक्षित है"], ["Entering the PIN reverses all prior transactions", "PIN डालने से पहले के सभी लेनदेन वापस हो जाते हैं"]], 0, "A PIN authorizes a debit; do not enter it to receive a refund or approve an unsolicited request.", "PIN डेबिट अधिकृत करता है; रिफंड पाने के लिए इसे न डालें और अनचाहा अनुरोध स्वीकार न करें।"),

        q("future-skills-cybersecurity", "Moderate", "A machine-learning model performs well on its training examples but poorly on new examples. Which issue is the most likely explanation?", "मशीन-लर्निंग मॉडल प्रशिक्षण उदाहरणों पर अच्छा चलता है लेकिन नए उदाहरणों पर खराब। सबसे संभावित कारण क्या है?", [["Overfitting to the training data", "प्रशिक्षण डेटा पर ओवरफिटिंग"], ["Successful generalization", "सफल सामान्यीकरण"], ["Strong encryption", "मजबूत एन्क्रिप्शन"], ["High network availability", "उच्च नेटवर्क उपलब्धता"]], 0, "Overfitting means a model has learned training-specific patterns that do not generalize well to unseen data.", "ओवरफिटिंग में मॉडल प्रशिक्षण-विशिष्ट पैटर्न सीखता है जो अनदेखे डेटा पर अच्छी तरह लागू नहीं होते।"),
        q("future-skills-cybersecurity", "Hard", "An attacker has a user's password but cannot enter the account without a time-based code from a separate authenticator. Which control is providing the additional barrier?", "हमलावर के पास उपयोगकर्ता का पासवर्ड है, पर अलग authenticator के समय-आधारित कोड के बिना खाते में नहीं जा सकता। अतिरिक्त सुरक्षा कौन-सा नियंत्रण दे रहा है?", [["Multi-factor authentication", "मल्टी-फैक्टर प्रमाणीकरण"], ["File compression", "फाइल संपीड़न"], ["Public DNS resolution", "सार्वजनिक DNS समाधान"], ["Data deduplication", "डेटा डिडुप्लिकेशन"]], 0, "Multi-factor authentication requires another independent factor, so a stolen password alone is insufficient.", "मल्टी-फैक्टर प्रमाणीकरण एक स्वतंत्र अतिरिक्त कारक माँगता है, इसलिए केवल चोरी हुआ पासवर्ड पर्याप्त नहीं होता।"),
        q("computer-fundamentals", "Moderate", "A system must preserve firmware settings when power is removed while allowing the processor to update those settings occasionally. Which memory characteristic fits best?", "बिजली हटाने पर सिस्टम को firmware settings बचाकर रखनी हैं, लेकिन processor को कभी-कभी उन्हें बदलने देना है। कौन-सी memory विशेषता सबसे उपयुक्त है?", [["Non-volatile rewritable memory such as flash", "Flash जैसी non-volatile rewritable memory"], ["Volatile cache that clears on power loss", "बिजली जाते ही मिटने वाली volatile cache"], ["CPU register storage", "CPU register storage"], ["A display frame buffer only", "केवल display frame buffer"]], 0, "Flash retains contents without power and can be rewritten, unlike volatile working memory.", "Flash बिजली के बिना सामग्री रखती है और दोबारा लिखी जा सकती है, volatile working memory के विपरीत।"),
        q("operating-system", "Hard", "Two users share a workstation. A document should be readable by its owner and a project group, but not by other users. Which OS mechanism should be configured?", "दो उपयोगकर्ता एक workstation साझा करते हैं। दस्तावेज़ उसका मालिक और project group पढ़ सकें, लेकिन अन्य उपयोगकर्ता नहीं। OS में कौन-सा तंत्र configure करना चाहिए?", [["File permissions or an access-control list", "File permissions या access-control list"], ["A file extension association", "File extension association"], ["A process scheduling priority", "Process scheduling priority"], ["A display resolution profile", "Display resolution profile"]], 0, "File permissions or ACLs grant access to specified users and groups.", "File permissions या ACL निर्दिष्ट उपयोगकर्ताओं और समूहों को पहुँच देते हैं।"),
        q("word-processing", "Easy", "A report's next chapter must always begin at the top of a new page even after earlier text is edited. Which feature is more robust than pressing Enter repeatedly?", "रिपोर्ट का अगला अध्याय पहले का टेक्स्ट बदलने के बाद भी हमेशा नए पेज के ऊपर शुरू होना चाहिए। बार-बार Enter दबाने से अधिक विश्वसनीय सुविधा कौन-सी है?", [["Insert a page break before the chapter heading", "अध्याय शीर्षक से पहले page break डालें"], ["Add blank paragraphs until it moves down", "नीचे ले जाने के लिए खाली paragraphs जोड़ें"], ["Change the heading font size", "शीर्षक का font size बदलें"], ["Use several spaces before the heading", "शीर्षक से पहले कई spaces दें"]], 0, "A page break controls pagination directly and remains stable when surrounding text changes.", "Page break सीधे pagination नियंत्रित करता है और आसपास का टेक्स्ट बदलने पर स्थिर रहता है।"),
        q("spreadsheet", "Hard", "A formula should return a tax rate from a two-column table whose first column contains lower-bound income values sorted ascending. Which lookup behavior is appropriate for bracket selection?", "सूत्र को ऐसी दो-कॉलम तालिका से tax rate लौटाना है जिसमें पहला कॉलम न्यूनतम income सीमाएँ ascending क्रम में हैं। bracket चुनने के लिए कौन-सा lookup व्यवहार उचित है?", [["Approximate match for the greatest lower bound not exceeding income", "आय से अधिक न होने वाली सबसे बड़ी lower bound का approximate match"], ["Exact match only, even when income lies inside a bracket", "केवल exact match, भले आय bracket के भीतर हो"], ["Wildcard match on the tax-rate text", "tax-rate टेक्स्ट पर wildcard match"], ["Lookup the last row regardless of income", "आय से स्वतंत्र अंतिम row देखना"]], 0, "Bracket tables use the greatest lower-bound threshold at or below the lookup value.", "Bracket तालिका में lookup value से कम या बराबर सबसे बड़ी lower-bound सीमा उपयोग होती है।"),
        q("presentation", "Hard", "An animation sequence must begin only after the presenter clicks, then reveal three chart series one at a time. Which timing setup best matches this requirement?", "Animation क्रम presenter के क्लिक के बाद ही शुरू हो और फिर chart की तीन series एक-एक करके दिखाए। कौन-सी timing व्यवस्था उपयुक्त है?", [["Set the first effect to On Click and later effects to After Previous", "पहला effect On Click और अगले After Previous रखें"], ["Set every effect to With Previous", "हर effect With Previous रखें"], ["Set every effect to After Previous with no initial trigger", "बिना शुरुआती trigger सभी After Previous रखें"], ["Use slide transition timing instead of object effects", "object effects की जगह slide transition timing उपयोग करें"]], 0, "The first click starts the sequence; After Previous chains later series in order.", "पहला क्लिक क्रम शुरू करता है; After Previous बाद की series को क्रम से चलाता है।"),
        q("internet-www", "Easy", "A host on one subnet must send a packet to a destination on another subnet. Which local network device normally forwards it toward the destination network?", "एक subnet का host दूसरे subnet के destination को packet भेजता है। कौन-सा स्थानीय network device उसे सामान्यतः destination network की ओर forward करता है?", [["Default gateway/router", "Default gateway/router"], ["DNS resolver", "DNS resolver"], ["Web proxy cache only", "केवल web proxy cache"], ["Network interface loopback", "Network interface loopback"]], 0, "A router or default gateway forwards traffic between IP networks.", "Router या default gateway अलग IP networks के बीच traffic forward करता है।"),
        q("email-egovernance", "Easy", "A recipient needs to send a message to many people without disclosing their addresses to one another. Which mail field is intended for this privacy?", "प्राप्तकर्ता को कई लोगों को ऐसा संदेश भेजना है कि उनके पते एक-दूसरे को दिखाई न दें। इस गोपनीयता के लिए कौन-सा mail field है?", [["Bcc", "Bcc"], ["To", "To"], ["Cc", "Cc"], ["Reply-To", "Reply-To"]], 0, "Bcc hides the listed recipients from other recipients of the message.", "Bcc सूचीबद्ध प्राप्तकर्ताओं को संदेश के अन्य प्राप्तकर्ताओं से छिपाता है।"),
        q("digital-finance", "Hard", "A customer sees a card transaction they did not authorize. What is the best immediate response?", "ग्राहक को card पर ऐसा transaction दिखता है जिसे उसने authorize नहीं किया। सबसे उचित तात्कालिक कदम क्या है?", [["Contact the issuer through its official channel and block or secure the card", "जारीकर्ता से आधिकारिक माध्यम से संपर्क कर card block या सुरक्षित करें"], ["Share the OTP with anyone claiming to reverse it", "वापसी का दावा करने वाले किसी भी व्यक्ति को OTP बताएँ"], ["Wait for a social-media reply before acting", "कार्रवाई से पहले social-media उत्तर की प्रतीक्षा करें"], ["Send the full card number in an open post", "पूरा card number सार्वजनिक पोस्ट में भेजें"]], 0, "Prompt issuer notification can block further misuse; OTPs and card credentials must remain private.", "जारीकर्ता को तुरंत सूचित करने से आगे का दुरुपयोग रोका जा सकता है; OTP और card credentials निजी रखें।"),
        q("future-skills-cybersecurity", "Moderate", "A team wants to restore files after ransomware encrypts the working copy. Which preparation most directly supports recovery?", "Ransomware द्वारा working copy encrypt किए जाने के बाद टीम को फाइलें restore करनी हैं। कौन-सी तैयारी recovery में सीधे मदद करती है?", [["Maintain tested, versioned backups isolated from routine write access", "सामान्य write access से अलग tested, versioned backups रखें"], ["Keep the only backup mounted and writable at all times", "एकमात्र backup हमेशा mounted और writable रखें"], ["Store passwords beside each file", "हर file के पास passwords रखें"], ["Disable all restore testing", "सभी restore परीक्षण बंद करें"]], 0, "Isolated backups reduce the chance that ransomware can encrypt the recovery copy; restore tests verify usability.", "अलग backups ransomware द्वारा recovery copy encrypt होने की आशंका घटाते हैं; restore tests उपयोगिता जाँचते हैं।"),

        q("computer-fundamentals", "Moderate", "Which CPU component performs arithmetic calculations and logical comparisons on data?", "डेटा पर अंकगणितीय गणना और तार्किक तुलना CPU का कौन-सा भाग करता है?", [["Arithmetic Logic Unit (ALU)", "Arithmetic Logic Unit (ALU)"], ["Control unit", "Control unit"], ["Power supply", "Power supply"], ["Input controller", "Input controller"]], 0, "The ALU performs arithmetic operations and logical comparisons as part of instruction execution.", "ALU निर्देश निष्पादन के दौरान अंकगणितीय संक्रियाएँ और तार्किक तुलनाएँ करता है।", "Expected Practice"),
        q("computer-fundamentals", "Moderate", "What is the binary representation of decimal 45?", "दशमलव 45 का बाइनरी निरूपण क्या है?", [["101101", "101101"], ["101011", "101011"], ["110101", "110101"], ["111001", "111001"]], 0, "45 is 32 + 8 + 4 + 1, so the 32, 8, 4 and 1 binary places are set: 101101.", "45 = 32 + 8 + 4 + 1 है, इसलिए 32, 8, 4 और 1 वाले बाइनरी स्थान सक्रिय हैं: 101101।", "Expected Practice"),
        q("computer-fundamentals", "Moderate", "A teacher needs to display a computer's output to a whole classroom without producing a paper copy. Which device is most suitable?", "शिक्षक को बिना कागज़ी प्रति बनाए पूरी कक्षा को कंप्यूटर का आउटपुट दिखाना है। कौन-सा उपकरण सबसे उपयुक्त है?", [["Projector", "प्रोजेक्टर"], ["Flatbed scanner", "फ्लैटबेड स्कैनर"], ["Barcode reader", "बारकोड रीडर"], ["Microphone", "माइक्रोफ़ोन"]], 0, "A projector presents visual computer output to a large audience as a soft copy.", "प्रोजेक्टर कंप्यूटर के दृश्य आउटपुट को बड़ी दर्शक-समूह के सामने सॉफ्ट कॉपी के रूप में दिखाता है।", "Expected Practice"),
        q("computer-fundamentals", "Moderate", "Which description best fits the main memory that temporarily holds programs and data currently in use?", "वर्तमान में उपयोग हो रहे प्रोग्राम और डेटा को अस्थायी रूप से रखने वाली मुख्य मेमोरी का सही वर्णन कौन-सा है?", [["RAM, which is volatile", "RAM, जो volatile होती है"], ["ROM, which is always rewritten by each application", "ROM, जिसे हर application हमेशा फिर लिखती है"], ["An optical disc, which is CPU main memory", "ऑप्टिकल डिस्क, जो CPU की मुख्य मेमोरी है"], ["A printer queue, which stores running instructions", "प्रिंटर कतार, जो चल रहे निर्देश रखती है"]], 0, "RAM is working memory for active programs and normally loses its contents when power is removed.", "RAM सक्रिय प्रोग्रामों की working memory है और बिजली हटने पर सामान्यतः इसकी सामग्री मिट जाती है।", "Expected Practice"),
        q("computer-fundamentals", "Moderate", "Which type of software is primarily intended to reduce the size of files for storage or transfer?", "फाइलों को स्टोरेज या स्थानांतरण के लिए छोटा करने का मुख्य उद्देश्य किस प्रकार के सॉफ़्टवेयर का है?", [["Utility software", "Utility software"], ["Presentation software", "Presentation software"], ["A device firmware setting", "Device firmware setting"], ["A programming-language translator only", "केवल programming-language translator"]], 0, "File-compression programs are utility software that help manage storage and transfer.", "फाइल-संपीड़न प्रोग्राम utility software हैं जो स्टोरेज और स्थानांतरण प्रबंधित करने में मदद करते हैं।", "Expected Practice"),
        q("computer-fundamentals", "Hard", "Add the binary numbers 101101 and 11011. What is their sum in binary?", "बाइनरी संख्याओं 101101 और 11011 को जोड़ें। उनका योग बाइनरी में क्या होगा?", [["1001000", "1001000"], ["1000110", "1000110"], ["111000", "111000"], ["1011000", "1011000"]], 0, "101101₂ is 45 and 11011₂ is 27; 45 + 27 = 72, which is 1001000₂.", "101101₂ = 45 और 11011₂ = 27; 45 + 27 = 72, जिसका बाइनरी रूप 1001000₂ है।", "Expected Practice"),
        q("computer-fundamentals", "Hard", "Which hexadecimal value represents decimal 156?", "दशमलव 156 का हेक्साडेसिमल मान कौन-सा है?", [["9C", "9C"], ["8C", "8C"], ["AC", "AC"], ["9A", "9A"]], 0, "156 divided by 16 gives quotient 9 and remainder 12; hexadecimal 12 is C, giving 9C.", "156 को 16 से भाग देने पर भागफल 9 और शेष 12 मिलता है; हेक्साडेसिमल 12 को C लिखते हैं, इसलिए मान 9C है।", "Expected Practice"),
        q("computer-fundamentals", "Hard", "During a memory read, which bus carries the location of the requested memory cell from the processor?", "मेमोरी read के दौरान processor से माँगे गए memory cell का स्थान कौन-सी bus ले जाती है?", [["Address bus", "Address bus"], ["Data bus", "Data bus"], ["Control bus", "Control bus"], ["Audio bus", "Audio bus"]], 0, "The address bus identifies the location; the data bus carries the value, while control signals specify the operation.", "Address bus स्थान बताती है; data bus मान ले जाती है, जबकि control signals operation बताते हैं।", "Expected Practice"),

        q("operating-system", "Moderate", "A user types commands such as copy and rename instead of selecting icons. Which operating-system interface is being used?", "उपयोगकर्ता icons चुनने के बजाय copy और rename जैसे commands टाइप करता है। कौन-सा operating-system interface उपयोग हो रहा है?", [["Command-line interface", "Command-line interface"], ["Graphical user interface", "Graphical user interface"], ["Touch-only interface", "केवल touch interface"], ["Firmware setup screen", "Firmware setup screen"]], 0, "A command-line interface accepts text commands from the user.", "Command-line interface उपयोगकर्ता से टेक्स्ट commands स्वीकार करता है।", "Expected Practice"),
        q("operating-system", "Moderate", "Which file path is an absolute path on a Windows system?", "Windows सिस्टम में कौन-सा file path absolute path है?", [["C:\\Users\\Asha\\Notes\\plan.txt", "C:\\Users\\Asha\\Notes\\plan.txt"], ["..\\Notes\\plan.txt", "..\\Notes\\plan.txt"], ["Notes\\plan.txt relative to the current folder", "वर्तमान folder के सापेक्ष Notes\\plan.txt"], ["plan.txt with no location specified", "बिना स्थान बताए केवल plan.txt"]], 0, "An absolute Windows path begins with a drive or root location and identifies the full route to the file.", "Absolute Windows path drive या root स्थान से शुरू होकर file तक का पूरा मार्ग बताता है।", "Expected Practice"),
        q("operating-system", "Moderate", "A program appears frozen, and a user wants to inspect its current CPU and memory use before closing it. Which utility is most appropriate?", "एक program अटका हुआ दिखता है और बंद करने से पहले उपयोगकर्ता उसका CPU तथा memory उपयोग देखना चाहता है। कौन-सी utility उपयुक्त है?", [["Task Manager or system monitor", "Task Manager या system monitor"], ["Text editor", "Text editor"], ["Screen magnifier", "Screen magnifier"], ["Disk defragmenter only", "केवल disk defragmenter"]], 0, "A task or system monitor shows running processes and their resource use, and commonly allows a task to be ended.", "Task या system monitor चल रही प्रक्रियाएँ और उनका resource उपयोग दिखाता है तथा सामान्यतः task बंद करने देता है।", "Expected Practice"),
        q("operating-system", "Moderate", "What allows an operating system to communicate correctly with a newly attached printer model?", "नए जुड़े printer model से operating system को सही संवाद करने में क्या मदद मिलती है?", [["A device driver", "Device driver"], ["A file extension", "File extension"], ["A screen saver", "Screen saver"], ["A spreadsheet formula", "Spreadsheet formula"]], 0, "A device driver translates operating-system requests into operations understood by a hardware device.", "Device driver operating-system अनुरोधों को हार्डवेयर द्वारा समझे जाने वाले कार्यों में बदलता है।", "Expected Practice"),
        q("operating-system", "Moderate", "A user wants to find every document containing a particular word without opening files one by one. Which built-in capability is most useful?", "उपयोगकर्ता हर file खोले बिना किसी शब्द वाली सभी documents ढूँढना चाहता है। कौन-सी built-in क्षमता सबसे उपयोगी है?", [["File search using a name or content index", "नाम या content index से file search"], ["Changing the desktop wallpaper", "Desktop wallpaper बदलना"], ["Adjusting speaker volume", "Speaker volume बदलना"], ["Changing the mouse pointer shape", "Mouse pointer का आकार बदलना"]], 0, "Operating-system file search can locate files by name and, when indexed, by their contents.", "Operating-system file search नाम से और index उपलब्ध होने पर सामग्री से भी files ढूँढ सकता है।", "Expected Practice"),
        q("operating-system", "Hard", "A process is waiting for data from a disk and cannot make progress yet. Which process state best describes it?", "एक process disk से डेटा की प्रतीक्षा कर रही है और अभी आगे नहीं बढ़ सकती। कौन-सी process state इसका सही वर्णन करती है?", [["Blocked or waiting", "Blocked या waiting"], ["Running", "Running"], ["Ready to use the CPU", "CPU उपयोग के लिए ready"], ["Terminated successfully", "सफलतापूर्वक terminated"]], 0, "A blocked process waits for an event or I/O completion rather than competing for CPU time as a ready process does.", "Blocked process किसी event या I/O पूरा होने की प्रतीक्षा करती है; ready process की तरह CPU समय के लिए प्रतिस्पर्धा नहीं करती।", "Expected Practice"),
        q("operating-system", "Hard", "In round-robin scheduling, what is the usual effect of making the time quantum extremely small for many CPU-bound processes?", "Round-robin scheduling में कई CPU-bound processes के लिए time quantum बहुत छोटा करने का सामान्य प्रभाव क्या है?", [["Context-switch overhead rises and useful CPU time may fall", "Context-switch overhead बढ़ता है और उपयोगी CPU समय घट सकता है"], ["Every process completes in one quantum", "हर process एक quantum में पूरी हो जाती है"], ["The system no longer needs a scheduler", "सिस्टम को scheduler की आवश्यकता नहीं रहती"], ["Blocked processes become permanent files", "Blocked processes स्थायी files बन जाती हैं"]], 0, "A tiny quantum causes frequent context switches, spending a larger share of time on scheduling overhead.", "बहुत छोटा quantum बार-बार context switch कराता है, जिससे scheduling overhead पर अधिक समय लगता है।", "Expected Practice"),
        q("operating-system", "Hard", "An administrator wants to diagnose a startup problem while loading only essential services and drivers. Which startup mode is designed for this purpose?", "Administrator केवल आवश्यक services और drivers लोड करके startup समस्या जाँचना चाहता है। किस startup mode का उद्देश्य यही है?", [["Safe mode or a minimal diagnostic boot", "Safe mode या minimal diagnostic boot"], ["Normal boot with every startup application", "हर startup application के साथ normal boot"], ["Sleep mode", "Sleep mode"], ["A screen-lock session", "Screen-lock session"]], 0, "A minimal diagnostic startup reduces nonessential components, helping isolate software or driver problems.", "Minimal diagnostic startup गैर-ज़रूरी घटकों को कम करता है, जिससे software या driver समस्याएँ अलग पहचानने में मदद मिलती है।", "Expected Practice"),

        q("word-processing", "Moderate", "A document repeatedly contains a company name that is often mistyped. Which feature can automatically replace a known incorrect form as the user types?", "दस्तावेज़ में कंपनी का नाम बार-बार आता है और अक्सर गलत टाइप होता है। टाइप करते समय ज्ञात गलत रूप को स्वतः बदलने वाली सुविधा कौन-सी है?", [["AutoCorrect", "AutoCorrect"], ["Mail merge", "Mail merge"], ["Page orientation", "Page orientation"], ["Word count", "Word count"]], 0, "AutoCorrect can replace configured misspellings or shortcuts with the intended text.", "AutoCorrect निर्धारित गलत वर्तनी या shortcuts को इच्छित टेक्स्ट से बदल सकता है।", "Expected Practice"),
        q("word-processing", "Moderate", "Several reviewers suggest edits, and the author needs to see each change and decide whether to keep it. Which feature should be enabled?", "कई reviewers बदलाव सुझाते हैं और लेखक को हर बदलाव देखकर उसे स्वीकार या अस्वीकार करना है। कौन-सी सुविधा चालू करनी चाहिए?", [["Track Changes", "Track Changes"], ["AutoSave only", "केवल AutoSave"], ["Page color", "Page color"], ["Find and Replace without recording", "बिना रिकॉर्ड किए Find and Replace"]], 0, "Track Changes records insertions and deletions so the author can review, accept, or reject them.", "Track Changes जोड़ और हटाव रिकॉर्ड करता है ताकि लेखक उनकी समीक्षा, स्वीकृति या अस्वीकृति कर सके।", "Expected Practice"),
        q("word-processing", "Moderate", "A report needs a brief source citation at the bottom of the page where the cited text appears. Which document feature fits this need?", "रिपोर्ट में उद्धृत टेक्स्ट वाले पृष्ठ के नीचे छोटा source citation चाहिए। कौन-सी document सुविधा उपयुक्त है?", [["Footnote", "Footnote"], ["Header", "Header"], ["Watermark", "Watermark"], ["Page border", "Page border"]], 0, "A footnote places explanatory or citation text at the bottom of the relevant page.", "Footnote संबंधित पृष्ठ के नीचे व्याख्या या citation टेक्स्ट रखता है।", "Expected Practice"),
        q("word-processing", "Moderate", "A single landscape table must sit between portrait pages, while the rest of the document remains unchanged. What should the author insert around that portion?", "एक landscape तालिका portrait पृष्ठों के बीच होनी चाहिए और दस्तावेज़ का बाकी भाग अपरिवर्तित रहे। उस भाग के आसपास क्या डालना चाहिए?", [["Section breaks", "Section breaks"], ["Repeated paragraph marks", "बार-बार paragraph marks"], ["A column break only", "केवल column break"], ["A text highlight", "Text highlight"]], 0, "Section breaks let a document apply different page orientation or layout settings to one section.", "Section breaks दस्तावेज़ के एक section पर अलग page orientation या layout लागू करने देते हैं।", "Expected Practice"),
        q("word-processing", "Moderate", "A long table continues on the next page. Which setting helps readers identify the columns on each continued page?", "एक लंबी तालिका अगले पृष्ठ पर जारी रहती है। जारी पृष्ठों पर पाठकों को columns पहचानने में कौन-सी setting मदद करती है?", [["Repeat the table's header row", "तालिका की header row दोहराएँ"], ["Insert blank rows before every page", "हर पृष्ठ से पहले खाली पंक्तियाँ डालें"], ["Convert every cell to an image", "हर cell को image में बदलें"], ["Turn off page breaks", "Page breaks बंद करें"]], 0, "Repeating the header row displays the column labels again when the table continues onto another page.", "Header row दोहराने से तालिका अगले पृष्ठ पर जारी होने पर column labels फिर दिखाई देते हैं।", "Expected Practice"),
        q("word-processing", "Hard", "A chapter heading should stay with the first paragraph that follows it, rather than being left alone at the bottom of a page. Which paragraph setting is designed for this?", "अध्याय शीर्षक को अगले पहले अनुच्छेद के साथ रहना चाहिए, न कि पृष्ठ के नीचे अकेला। इसके लिए कौन-सी paragraph setting बनाई गई है?", [["Keep with next", "Keep with next"], ["Keep lines together on every page", "हर पृष्ठ पर सभी पंक्तियाँ साथ रखें"], ["Different first-page header", "अलग first-page header"], ["Mirror margins", "Mirror margins"]], 0, "Keep with next keeps the heading on the same page as the following paragraph when pagination changes.", "Keep with next pagination बदलने पर शीर्षक को अगले अनुच्छेद के साथ उसी पृष्ठ पर रखता है।", "Expected Practice"),
        q("word-processing", "Hard", "Page numbers in a later section must restart at 1 without changing the numbering of earlier sections. What combination is appropriate?", "बाद के section में page numbering को 1 से फिर शुरू करना है, पर पहले sections की numbering नहीं बदलनी चाहिए। कौन-सा संयोजन उचित है?", [["Insert a section break, unlink its header/footer, then set numbering to start at 1", "Section break डालें, header/footer का link हटाएँ, फिर numbering 1 से शुरू करें"], ["Add page breaks and type every number manually", "Page breaks डालकर हर number हाथ से टाइप करें"], ["Change the document font", "दस्तावेज़ का font बदलें"], ["Use a column break and keep linked numbering", "Column break उपयोग कर linked numbering रखें"]], 0, "A separate section can have independent page numbering once its header or footer is unlinked from the previous section.", "पिछले section से header या footer का link हटाने पर अलग section में स्वतंत्र page numbering रखी जा सकती है।", "Expected Practice"),
        q("word-processing", "Hard", "A figure number such as Figure 4 is mentioned elsewhere in a report and may change when figures are added. Which feature makes the mention update reliably?", "रिपोर्ट में Figure 4 का उल्लेख दूसरी जगह है और नई figures जुड़ने पर संख्या बदल सकती है। उल्लेख को विश्वसनीय रूप से अपडेट करने वाली सुविधा कौन-सी है?", [["A cross-reference linked to the figure caption", "Figure caption से जुड़ा cross-reference"], ["A manually typed number", "हाथ से टाइप किया गया number"], ["A text box copied from the caption", "Caption से copy किया गया text box"], ["A page-color setting", "Page-color setting"]], 0, "A cross-reference points to a caption or other numbered item and can be refreshed when numbering changes.", "Cross-reference caption या अन्य numbered item से जुड़ता है और numbering बदलने पर refresh किया जा सकता है।", "Expected Practice"),

        q("spreadsheet", "Moderate", "A cell stores the number 0.25 but should display it as 25%. Which change preserves the underlying numeric value for calculations?", "एक cell में 0.25 संख्या है, पर उसे 25% दिखाना है। गणना के लिए मूल संख्यात्मक मान बनाए रखने वाला बदलाव कौन-सा है?", [["Apply percentage number formatting", "Percentage number formatting लागू करें"], ["Replace the value with the text 25%", "मान को 25% टेक्स्ट से बदलें"], ["Merge the cell with another cell", "Cell को दूसरे cell से merge करें"], ["Sort the worksheet", "Worksheet को sort करें"]], 0, "Percentage formatting changes how 0.25 is displayed, while leaving its numeric value available to formulas.", "Percentage formatting 0.25 का प्रदर्शन बदलती है, जबकि उसका संख्यात्मक मान formulas के लिए उपलब्ध रहता है।", "Expected Practice"),
        q("spreadsheet", "Moderate", "Column A contains regions and column B contains sales. Which function can total sales only for rows where the region is North?", "कॉलम A में क्षेत्र और कॉलम B में बिक्री है। केवल North क्षेत्र वाली पंक्तियों की बिक्री जोड़ने के लिए कौन-सा function उपयोग होगा?", [["SUMIF", "SUMIF"], ["COUNTBLANK", "COUNTBLANK"], ["LEFT", "LEFT"], ["NOW", "NOW"]], 0, "SUMIF adds values from a sum range when corresponding cells meet one specified condition.", "SUMIF एक निर्दिष्ट शर्त पूरी करने वाली संबंधित कोशिकाओं के sum range मान जोड़ता है।", "Expected Practice"),
        q("spreadsheet", "Moderate", "A worksheet has hundreds of rows, and the user wants column headings to remain visible while scrolling down. Which feature should be used?", "Worksheet में सैकड़ों पंक्तियाँ हैं और नीचे scroll करते समय column headings दिखते रहने चाहिए। कौन-सी सुविधा उपयोग करें?", [["Freeze the heading row", "Heading row को freeze करें"], ["Hide the heading row", "Heading row छिपाएँ"], ["Sort headings to the bottom", "Headings को नीचे sort करें"], ["Convert the sheet to plain text", "Sheet को plain text में बदलें"]], 0, "Freeze Panes keeps selected rows or columns visible while the rest of the worksheet scrolls.", "Freeze Panes चयनित पंक्तियों या columns को दृश्यमान रखता है जबकि बाकी worksheet scroll होती है।", "Expected Practice"),
        q("spreadsheet", "Moderate", "An entry cell should accept only whole numbers from 1 through 50. Which feature can enforce this rule at input time?", "Entry cell में केवल 1 से 50 तक की पूर्ण संख्याएँ स्वीकार होनी चाहिए। Input के समय यह नियम कौन-सी सुविधा लागू कर सकती है?", [["Data validation", "Data validation"], ["Conditional formatting", "Conditional formatting"], ["A chart legend", "Chart legend"], ["Find and Replace", "Find and Replace"]], 0, "Data validation restricts allowed entries and can show an input message or error alert.", "Data validation अनुमत entries सीमित करता है और input संदेश या error alert दिखा सकता है।", "Expected Practice"),
        q("spreadsheet", "Moderate", "A manager wants to display only rows for the East region without deleting or rearranging the underlying records. Which operation is appropriate?", "Manager मूल records हटाए या उनका क्रम बदले बिना केवल East क्षेत्र की पंक्तियाँ दिखाना चाहता है। कौन-सी क्रिया उपयुक्त है?", [["Filter the region column", "Region column को filter करें"], ["Delete all other regions", "अन्य सभी क्षेत्रों को delete करें"], ["Sort the workbook alphabetically", "Workbook को alphabetically sort करें"], ["Merge the region cells", "Region cells को merge करें"]], 0, "Filtering temporarily hides rows that do not meet the selected criterion without removing the source records.", "Filtering चुनी गई शर्त पूरी न करने वाली पंक्तियाँ अस्थायी रूप से छिपाता है, source records हटाता नहीं।", "Expected Practice"),
        q("spreadsheet", "Hard", "A sales table has one row per transaction. Which tool can summarize total sales by product and region without writing a separate formula for every combination?", "Sales table में हर transaction की एक पंक्ति है। हर संयोजन के लिए अलग formula लिखे बिना product और region के अनुसार कुल बिक्री कौन-सा tool summarize कर सकता है?", [["Pivot table", "Pivot table"], ["Spell checker", "Spell checker"], ["Cell comment", "Cell comment"], ["Page-break preview", "Page-break preview"]], 0, "A pivot table groups records by chosen fields and aggregates values such as sales totals.", "Pivot table चुने हुए fields के अनुसार records समूहित करता है और sales total जैसे मानों का aggregation करता है।", "Expected Practice"),
        q("spreadsheet", "Hard", "A formula divides A2 by B2, but B2 can be zero. Which pattern displays a clear message instead of an error when division fails?", "एक formula A2 को B2 से भाग देता है, लेकिन B2 शून्य हो सकता है। भाग विफल होने पर error की जगह स्पष्ट संदेश दिखाने वाला pattern कौन-सा है?", [["IFERROR(A2/B2, \"Check denominator\")", "IFERROR(A2/B2, \"Check denominator\")"], ["SUM(A2:B2)", "SUM(A2:B2)"], ["COUNT(A2:B2)", "COUNT(A2:B2)"], ["A2+B2", "A2+B2"]], 0, "IFERROR returns the calculation result when valid and the chosen fallback value when an error occurs.", "IFERROR गणना सही होने पर उसका परिणाम और error होने पर चुना हुआ वैकल्पिक मान लौटाता है।", "Expected Practice"),
        q("spreadsheet", "Hard", "A chart's values are correct but its category labels show 1, 2, 3 instead of the month names in cells A2:A13. What should be corrected?", "Chart के मान सही हैं, लेकिन category labels में A2:A13 के महीने के नामों के बजाय 1, 2, 3 दिखता है। क्या ठीक करना चाहिए?", [["Set the horizontal category axis label range to A2:A13", "Horizontal category axis label range को A2:A13 करें"], ["Change the worksheet zoom", "Worksheet zoom बदलें"], ["Apply currency format to the labels", "Labels पर currency format लगाएँ"], ["Freeze the first column", "पहला column freeze करें"]], 0, "The chart's category-axis range must point to the cells containing the month names.", "Chart की category-axis range उन cells की ओर होनी चाहिए जिनमें महीनों के नाम हैं।", "Expected Practice"),

        q("presentation", "Moderate", "A slide uses pale text on a pale background, making it hard to read from the back of a room. Which change most directly improves legibility?", "स्लाइड में हल्के background पर हल्का टेक्स्ट है, इसलिए कमरे के पीछे से पढ़ना कठिन है। पठनीयता सीधे सुधारने वाला बदलाव कौन-सा है?", [["Use strongly contrasting text and background colors", "टेक्स्ट और background के लिए स्पष्ट contrast वाले रंग चुनें"], ["Add more decorative animations", "अधिक सजावटी animations जोड़ें"], ["Reduce the text size further", "टेक्स्ट का आकार और घटाएँ"], ["Place text over a busy photograph", "व्यस्त photograph पर टेक्स्ट रखें"]], 0, "Strong color contrast improves visibility, especially for projected slides and viewers with low vision.", "स्पष्ट रंग contrast दृश्यता सुधारता है, विशेषकर projected slides और कम दृष्टि वाले दर्शकों के लिए।", "Expected Practice"),
        q("presentation", "Moderate", "Which presentation area can hold reminders for the speaker that are not normally shown to the audience during the slide show?", "प्रस्तुति का कौन-सा भाग वक्ता के लिए reminders रख सकता है जो slide show के दौरान सामान्यतः दर्शकों को नहीं दिखते?", [["Speaker notes", "Speaker notes"], ["Slide title placeholder", "Slide title placeholder"], ["Transition pane", "Transition pane"], ["Slide number field", "Slide number field"]], 0, "Speaker notes support the presenter with prompts while the audience views the slide itself.", "दर्शक स्लाइड देखते हैं जबकि speaker notes वक्ता को संकेत देते हैं।", "Expected Practice"),
        q("presentation", "Moderate", "An author wants a new slide with a title area and two aligned content columns that match the presentation theme. What is the best starting point?", "लेखक को शीर्षक क्षेत्र और दो aligned content columns वाली नई स्लाइड चाहिए जो प्रस्तुति theme से मेल खाए। सबसे अच्छा आरंभ क्या है?", [["Choose a suitable slide layout", "उपयुक्त slide layout चुनें"], ["Draw every text box from scratch", "हर text box शुरू से बनाएँ"], ["Apply an animation before adding content", "सामग्री जोड़ने से पहले animation लगाएँ"], ["Insert a screenshot of another slide", "दूसरी स्लाइड का screenshot डालें"]], 0, "A slide layout provides coordinated placeholders and positioning for the intended content structure.", "Slide layout इच्छित सामग्री संरचना के लिए समन्वित placeholders और स्थान देता है।", "Expected Practice"),
        q("presentation", "Moderate", "A diagram conveys meaning through shapes and color, but a screen-reader user cannot interpret it. What should the author add?", "एक diagram आकार और रंग से अर्थ बताता है, लेकिन screen-reader उपयोगकर्ता उसे समझ नहीं सकता। लेखक को क्या जोड़ना चाहिए?", [["Meaningful alternative text or an equivalent description", "अर्थपूर्ण alternative text या समकक्ष विवरण"], ["More transition effects", "अधिक transition effects"], ["A hidden duplicate slide", "छिपी हुई duplicate slide"], ["A decorative border only", "केवल सजावटी border"]], 0, "Alternative text or a nearby equivalent description communicates important visual information nonvisually.", "Alternative text या पास का समकक्ष विवरण महत्वपूर्ण दृश्य जानकारी को बिना देखे समझाता है।", "Expected Practice"),
        q("presentation", "Moderate", "A presenter wants printed pages containing several slide thumbnails and space for audience notes. Which output format is designed for this?", "Presenter को कई slide thumbnails और दर्शकों के notes के लिए स्थान वाले printed pages चाहिए। किस output format का यही उद्देश्य है?", [["Handouts", "Handouts"], ["A full-screen slide show", "Full-screen slide show"], ["A single-slide poster only", "केवल एक-स्लाइड poster"], ["A transition preview", "Transition preview"]], 0, "Handout layouts place multiple slides on a page and can provide space for note-taking.", "Handout layouts एक पृष्ठ पर कई slides रखते हैं और notes लिखने की जगह दे सकते हैं।", "Expected Practice"),
        q("presentation", "Hard", "A presentation has a fade between slides and a motion path on a picture. Which statement correctly distinguishes these effects?", "प्रस्तुति में slides के बीच fade और चित्र पर motion path है। इन effects में सही अंतर क्या है?", [["The fade is a slide transition; the motion path animates an object", "Fade slide transition है; motion path किसी object को animate करता है"], ["Both are slide transitions", "दोनों slide transitions हैं"], ["Both are object animations", "दोनों object animations हैं"], ["The fade changes the slide master while the path changes its theme", "Fade slide master बदलता है जबकि path theme बदलता है"]], 0, "Transitions control movement between slides, whereas animations affect objects within a slide.", "Transitions slides के बीच बदलाव नियंत्रित करते हैं, जबकि animations एक slide के भीतर objects पर लागू होते हैं।", "Expected Practice"),
        q("presentation", "Hard", "A presenter wants slides to advance automatically at practiced intervals while retaining the recorded delivery sequence. Which feature should be configured?", "Presenter चाहता है कि अभ्यास किए गए अंतराल पर slides स्वतः आगे बढ़ें और recorded delivery sequence बना रहे। कौन-सी सुविधा configure करनी चाहिए?", [["Rehearse timings and use the recorded slide timings", "Rehearse timings करके recorded slide timings उपयोग करें"], ["Set every object to start on click", "हर object को click पर शुरू करें"], ["Apply one transition without duration settings", "Duration settings के बिना एक transition लगाएँ"], ["Print the speaker notes", "Speaker notes print करें"]], 0, "Rehearsal records time spent on each slide so the slide show can use those timings for automatic advancement.", "Rehearsal हर slide पर बिताया समय रिकॉर्ड करता है ताकि slide show स्वतः आगे बढ़ने के लिए उन timings का उपयोग करे।", "Expected Practice"),
        q("presentation", "Hard", "A presentation must open with the same fonts on computers that do not have those fonts installed. Which preparation best addresses this portability issue?", "जिन computers में आवश्यक fonts installed नहीं हैं, उन पर भी प्रस्तुति समान fonts के साथ खुलनी चाहिए। इस portability समस्या का सबसे अच्छा समाधान क्या है?", [["Embed fonts in the presentation when licensing and format permit", "अनुमति और format मिलने पर fonts को प्रस्तुति में embed करें"], ["Replace fonts with screenshots of every slide", "हर slide को font के screenshot से बदलें"], ["Disable all text placeholders", "सभी text placeholders बंद करें"], ["Use a different slide transition", "अलग slide transition उपयोग करें"]], 0, "Embedding permitted fonts can preserve text appearance on systems where those fonts are otherwise unavailable.", "अनुमत fonts embed करने से उन systems पर भी टेक्स्ट का रूप बना रह सकता है जहाँ वे fonts उपलब्ध नहीं हैं।", "Expected Practice"),

        q("internet-www", "Moderate", "In the URL https://portal.example.in:8443/help, what does 8443 identify?", "URL https://portal.example.in:8443/help में 8443 क्या बताता है?", [["The network port", "Network port"], ["The top-level domain", "Top-level domain"], ["The page fragment", "Page fragment"], ["The browser's search phrase", "Browser का search phrase"]], 0, "The number after a colon following the host is the port used for the connection.", "Host के बाद colon से लगा number connection के लिए उपयोग होने वाला port है।", "Expected Practice"),
        q("internet-www", "Moderate", "A search engine should find the exact phrase digital literacy rather than pages containing the two words separately. What query form is most useful?", "Search engine को digital literacy का सटीक phrase ढूँढना है, न कि दोनों शब्द अलग-अलग रखने वाले pages। कौन-सा query रूप उपयोगी है?", [["Put the phrase in quotation marks", "Phrase को quotation marks में रखें"], ["Prefix every word with a minus sign", "हर शब्द के आगे minus sign लगाएँ"], ["Search only for a file extension", "केवल file extension खोजें"], ["Replace the phrase with a random URL", "Phrase को किसी random URL से बदलें"]], 0, "Quotation marks commonly ask a search engine to match the words as an exact phrase.", "Quotation marks सामान्यतः search engine से शब्दों को सटीक phrase के रूप में मिलाने को कहते हैं।", "Expected Practice"),
        q("internet-www", "Moderate", "A shopping site remembers items in a basket between visits using small browser-stored data. Which browser mechanism is commonly used?", "एक shopping site visits के बीच basket की वस्तुएँ याद रखने के लिए browser में छोटा डेटा रखती है। सामान्यतः कौन-सा browser mechanism उपयोग होता है?", [["Cookie", "Cookie"], ["DNS record", "DNS record"], ["Router table", "Router table"], ["USB cache", "USB cache"]], 0, "Cookies can store small site-related identifiers or preferences that help a service maintain state.", "Cookies छोटी site-संबंधित पहचान या preferences रख सकती हैं जिनसे सेवा state बनाए रखती है।", "Expected Practice"),
        q("internet-www", "Moderate", "A user wants to use an online word processor through a browser without installing or maintaining the application. Which cloud service model best describes this?", "उपयोगकर्ता application install या maintain किए बिना browser से online word processor चलाना चाहता है। कौन-सा cloud service model इसका सही वर्णन करता है?", [["Software as a Service (SaaS)", "Software as a Service (SaaS)"], ["Infrastructure as a Service only", "केवल Infrastructure as a Service"], ["Local firmware service", "Local firmware service"], ["Offline file transfer protocol", "Offline file transfer protocol"]], 0, "SaaS provides a complete application as an online service, commonly accessed through a browser.", "SaaS एक पूर्ण application ऑनलाइन सेवा के रूप में देता है, जिसे सामान्यतः browser से उपयोग किया जाता है।", "Expected Practice"),
        q("internet-www", "Moderate", "A browser reloads a page using locally saved copies of images and style files. Which mechanism is helping avoid downloading every unchanged resource again?", "Browser images और style files की स्थानीय प्रतियों से page reload करता है। हर अपरिवर्तित resource फिर डाउनलोड करने से कौन-सा mechanism बचाता है?", [["Browser cache", "Browser cache"], ["Mail queue", "Mail queue"], ["Domain registration", "Domain registration"], ["A keyboard buffer", "Keyboard buffer"]], 0, "A browser cache stores reusable resources so a later page load may retrieve unchanged content locally.", "Browser cache दोबारा उपयोग योग्य resources रखता है ताकि बाद में अपरिवर्तित सामग्री स्थानीय रूप से मिल सके।", "Expected Practice"),
        q("internet-www", "Hard", "A live voice call should favor low delay and can tolerate occasional packet loss rather than waiting for retransmission. Which transport protocol is often suitable for this requirement?", "Live voice call में कम विलंब प्राथमिक है और retransmission की प्रतीक्षा के बजाय कभी-कभार packet loss स्वीकार्य है। इस आवश्यकता के लिए कौन-सा transport protocol अक्सर उपयुक्त है?", [["UDP", "UDP"], ["TCP with guaranteed ordered delivery", "Guaranteed ordered delivery वाला TCP"], ["SMTP", "SMTP"], ["DNS zone transfer", "DNS zone transfer"]], 0, "UDP avoids TCP's connection and retransmission behavior, making it useful for delay-sensitive real-time traffic.", "UDP, TCP के connection और retransmission व्यवहार से बचता है, इसलिए कम-विलंब real-time traffic में उपयोगी है।", "Expected Practice"),
        q("internet-www", "Hard", "An application must deliver a complete file in order and detect missing data before presenting it as complete. Which transport protocol is the usual choice?", "Application को पूरी file क्रम में पहुँचानी है और complete दिखाने से पहले छूटा डेटा पहचानना है। सामान्यतः कौन-सा transport protocol चुना जाता है?", [["TCP", "TCP"], ["UDP without application-level recovery", "Application-level recovery के बिना UDP"], ["ARP", "ARP"], ["ICMP echo only", "केवल ICMP echo"]], 0, "TCP provides reliable, ordered byte-stream delivery with retransmission of lost data.", "TCP खोए हुए डेटा के retransmission सहित विश्वसनीय और क्रमबद्ध byte-stream delivery देता है।", "Expected Practice"),
        q("internet-www", "Hard", "Which statement correctly describes an HTTP exchange between a browser and a web server?", "Browser और web server के बीच HTTP exchange का सही वर्णन कौन-सा है?", [["The browser sends a request and the server returns a response", "Browser request भेजता है और server response लौटाता है"], ["The server asks DNS to write the browser's files", "Server DNS से browser की files लिखवाता है"], ["The browser uses SMTP to render every web page", "Browser हर web page दिखाने के लिए SMTP उपयोग करता है"], ["HTTP is a file-system permission", "HTTP एक file-system permission है"]], 0, "HTTP defines request and response messages used to transfer web resources between clients and servers.", "HTTP clients और servers के बीच web resources स्थानांतरित करने के लिए request और response messages परिभाषित करता है।", "Expected Practice"),

        q("email-egovernance", "Moderate", "A user receives a message addressed to many people and wants to respond only to its sender. Which action avoids sending the response to the entire group?", "उपयोगकर्ता को कई लोगों को भेजा गया संदेश मिलता है और वह केवल भेजने वाले को जवाब देना चाहता है। कौन-सी क्रिया पूरे समूह को जवाब भेजने से बचाती है?", [["Choose Reply, not Reply All", "Reply चुनें, Reply All नहीं"], ["Forward it to every recipient", "इसे हर प्राप्तकर्ता को forward करें"], ["Add every recipient to Bcc", "हर प्राप्तकर्ता को Bcc में जोड़ें"], ["Use the attachment button", "Attachment button उपयोग करें"]], 0, "Reply sends a response to the sender, while Reply All also includes other recipients.", "Reply भेजने वाले को उत्तर देता है, जबकि Reply All अन्य प्राप्तकर्ताओं को भी शामिल करता है।", "Expected Practice"),
        q("email-egovernance", "Moderate", "Which protocol is commonly used by an email client to submit an outgoing message to a mail server?", "Outgoing message को mail server पर भेजने के लिए email client सामान्यतः कौन-सा protocol उपयोग करता है?", [["SMTP", "SMTP"], ["IMAP", "IMAP"], ["POP3 only for sending", "भेजने के लिए केवल POP3"], ["HTML", "HTML"]], 0, "SMTP is used to send or relay outgoing email; IMAP and POP are primarily used to retrieve mail.", "SMTP outgoing email भेजने या relay करने के लिए है; IMAP और POP मुख्यतः mail प्राप्त करने के लिए हैं।", "Expected Practice"),
        q("email-egovernance", "Moderate", "An email attachment is too large for the recipient's mailbox limit. What is a sensible way to share it?", "Email attachment प्राप्तकर्ता की mailbox सीमा से बड़ा है। इसे साझा करने का समझदारी भरा तरीका क्या है?", [["Use an approved file-sharing service and grant the recipient suitable access", "स्वीकृत file-sharing सेवा उपयोग करें और प्राप्तकर्ता को उचित access दें"], ["Rename it with a shorter filename and resend unchanged", "छोटा filename देकर बिना बदलाव फिर भेजें"], ["Send the password in a public post", "Password को सार्वजनिक post में भेजें"], ["Split the file randomly into email fragments", "File को बेतरतीब email टुकड़ों में बाँटें"]], 0, "A suitable sharing service handles large files and lets the sender control who can access them.", "उचित sharing सेवा बड़ी files संभालती है और भेजने वाले को access नियंत्रित करने देती है।", "Expected Practice"),
        q("email-egovernance", "Moderate", "A citizen wants to retrieve an issued digital document from a government-backed online repository. Which type of service is intended for this?", "नागरिक सरकारी समर्थित online repository से जारी digital document प्राप्त करना चाहता है। किस प्रकार की सेवा इसी के लिए है?", [["A digital document wallet or repository such as DigiLocker", "DigiLocker जैसी digital document wallet या repository"], ["A public social-media feed", "Public social-media feed"], ["An email spam folder", "Email spam folder"], ["A browser bookmark list", "Browser bookmark list"]], 0, "Digital document repositories let users access eligible issued records online after appropriate account verification.", "Digital document repositories उचित account verification के बाद उपयोगकर्ताओं को पात्र जारी रिकॉर्ड ऑनलाइन प्राप्त करने देती हैं।", "Expected Practice"),
        q("email-egovernance", "Moderate", "Before posting a photo that identifies a friend and reveals their location, what is the most responsible action?", "मित्र की पहचान और उसका स्थान दिखाने वाली photo post करने से पहले सबसे जिम्मेदार कदम क्या है?", [["Ask for consent and remove unnecessary location details", "सहमति लें और अनावश्यक location विवरण हटाएँ"], ["Tag everyone nearby without asking", "बिना पूछे पास के सभी लोगों को tag करें"], ["Publish the photo with the home address", "घर के पते सहित photo प्रकाशित करें"], ["Share the account password with the friend", "मित्र के साथ account password साझा करें"]], 0, "Consent and limiting location information reduce privacy exposure when sharing on social networks.", "सहमति लेना और location जानकारी सीमित करना social networks पर साझा करते समय privacy जोखिम घटाता है।", "Expected Practice"),
        q("email-egovernance", "Hard", "A public-service portal lets a user share one verified document with an agency. Which practice best follows data-minimization principles?", "Public-service portal उपयोगकर्ता को एक verified document किसी agency से साझा करने देता है। Data-minimization सिद्धांत के अनुरूप सर्वोत्तम तरीका कौन-सा है?", [["Share only the requested document with the intended agency and review its access scope", "केवल माँगा गया document इच्छित agency से साझा करें और access scope जाँचें"], ["Publish all stored documents to make verification easier", "सत्यापन सरल करने के लिए सभी stored documents प्रकाशित करें"], ["Send account credentials instead of the document", "Document की जगह account credentials भेजें"], ["Allow permanent public access to every record", "हर record का स्थायी public access दें"]], 0, "Data minimization limits disclosure to what is needed and to the intended recipient.", "Data minimization खुलासे को आवश्यक जानकारी और इच्छित प्राप्तकर्ता तक सीमित करता है।", "Expected Practice"),
        q("email-egovernance", "Hard", "A user must access a government service after receiving an OTP. Which handling is safest?", "OTP मिलने के बाद उपयोगकर्ता को सरकारी सेवा में प्रवेश करना है। उसे संभालने का सबसे सुरक्षित तरीका क्या है?", [["Enter it only in the official service flow the user initiated; never disclose it to callers", "इसे केवल स्वयं शुरू की गई आधिकारिक सेवा में दर्ज करें; caller को कभी न बताएँ"], ["Read it to anyone claiming to be support", "Support होने का दावा करने वाले किसी भी व्यक्ति को बताएँ"], ["Post it so an agent can validate the account", "Agent से account validate कराने के लिए इसे post करें"], ["Reuse it as a permanent password", "इसे स्थायी password की तरह दोबारा उपयोग करें"]], 0, "An OTP is a temporary authentication secret; entering it only in the expected official flow helps prevent account takeover.", "OTP अस्थायी authentication secret है; इसे केवल अपेक्षित आधिकारिक प्रक्रिया में दर्ज करने से account takeover रोकने में मदद मिलती है।", "Expected Practice"),
        q("email-egovernance", "Hard", "A government portal offers a downloadable receipt after an online application. What should a user do to preserve evidence of submission?", "सरकारी portal online application के बाद downloadable receipt देता है। जमा करने का प्रमाण सुरक्षित रखने के लिए उपयोगकर्ता को क्या करना चाहिए?", [["Download or securely save the receipt and note its reference number", "Receipt download या सुरक्षित रूप से save करें और reference number लिखें"], ["Assume the form was submitted before seeing confirmation", "Confirmation देखने से पहले मान लें कि form जमा हो गया"], ["Share the receipt publicly with personal details visible", "व्यक्तिगत विवरण सहित receipt सार्वजनिक साझा करें"], ["Delete all confirmation messages immediately", "सभी confirmation messages तुरंत delete करें"]], 0, "A receipt and reference number help confirm and later track the submitted application.", "Receipt और reference number जमा application की पुष्टि और बाद में tracking में मदद करते हैं।", "Expected Practice"),

        q("digital-finance", "Moderate", "At a business correspondent terminal, a customer authenticates with Aadhaar-linked details and a fingerprint to access basic banking. Which service is this?", "Business correspondent terminal पर ग्राहक basic banking के लिए Aadhaar-linked विवरण और fingerprint से authenticate करता है। यह कौन-सी सेवा है?", [["Aadhaar Enabled Payment System (AEPS)", "Aadhaar Enabled Payment System (AEPS)"], ["NEFT", "NEFT"], ["A credit-card chargeback", "Credit-card chargeback"], ["A mobile wallet top-up", "Mobile wallet top-up"]], 0, "AEPS supports specified banking transactions using Aadhaar authentication through an enabled micro-ATM or correspondent.", "AEPS सक्षम micro-ATM या correspondent के माध्यम से Aadhaar authentication से निर्धारित banking transactions करता है।", "Expected Practice"),
        q("digital-finance", "Moderate", "A customer needs to transfer money between bank accounts immediately at any time, including outside ordinary banking hours. Which channel is designed for real-time transfers?", "ग्राहक को सामान्य banking समय के बाहर भी किसी भी समय bank accounts के बीच तुरंत पैसा भेजना है। Real-time transfer के लिए कौन-सा channel बनाया गया है?", [["IMPS", "IMPS"], ["A paper cheque sent by post", "डाक से भेजा गया paper cheque"], ["A monthly account statement", "मासिक account statement"], ["A card's printed expiry date", "Card पर छपी expiry date"]], 0, "IMPS is an immediate electronic fund-transfer service available around the clock through participating institutions.", "IMPS भाग लेने वाले संस्थानों के माध्यम से चौबीसों घंटे उपलब्ध immediate electronic fund-transfer सेवा है।", "Expected Practice"),
        q("digital-finance", "Moderate", "What does a stored-value mobile wallet primarily hold for making eligible payments?", "योग्य भुगतान करने के लिए stored-value mobile wallet मुख्यतः क्या रखता है?", [["An electronic balance associated with the wallet", "Wallet से जुड़ा electronic balance"], ["The user's bank password in a public profile", "Public profile में उपयोगकर्ता का bank password"], ["A guarantee that every merchant is genuine", "यह गारंटी कि हर merchant असली है"], ["A physical cheque book", "भौतिक cheque book"]], 0, "A wallet can hold or represent an electronic balance that the user spends at supported merchants.", "Wallet electronic balance रख या दर्शा सकता है जिसे उपयोगकर्ता समर्थित merchants पर खर्च करता है।", "Expected Practice"),
        q("digital-finance", "Moderate", "A customer has sent a digital payment and wants evidence for a later query. Which information is most useful to retain?", "ग्राहक ने digital payment भेजा है और बाद में पूछताछ के लिए प्रमाण रखना चाहता है। कौन-सी जानकारी सहेजना सबसे उपयोगी है?", [["Transaction reference or UTR, amount and date", "Transaction reference या UTR, राशि और तारीख"], ["The account PIN written on the receipt", "Receipt पर लिखा account PIN"], ["A screenshot containing a full card security code", "पूरा card security code दिखाता screenshot"], ["The recipient's password", "प्राप्तकर्ता का password"]], 0, "A transaction reference with amount and date helps the bank or payment provider identify a transfer.", "राशि और तारीख के साथ transaction reference bank या payment provider को transfer पहचानने में मदद करता है।", "Expected Practice"),
        q("digital-finance", "Moderate", "Why should a customer check the recipient name and amount shown by a payment app before confirming?", "Payment app में पुष्टि से पहले प्राप्तकर्ता का नाम और राशि जाँचना क्यों चाहिए?", [["To catch a wrong recipient or amount before authorizing the transfer", "Transfer authorize करने से पहले गलत प्राप्तकर्ता या राशि पकड़ने के लिए"], ["To make the transaction reversible in every case", "हर स्थिति में transaction वापस करने योग्य बनाने के लिए"], ["To reveal the customer's PIN to the merchant", "ग्राहक का PIN merchant को बताने के लिए"], ["To disable transaction records", "Transaction records बंद करने के लिए"]], 0, "Reviewing the displayed payee and amount helps identify entry or selection mistakes before payment authorization.", "दिखाए गए payee और राशि की समीक्षा भुगतान authorize करने से पहले input या selection की गलती पहचानने में मदद करती है।", "Expected Practice"),
        q("digital-finance", "Hard", "A business is comparing NEFT with RTGS for a large bank transfer. Which statement best distinguishes the settlement design?", "एक व्यवसाय बड़े bank transfer के लिए NEFT और RTGS की तुलना कर रहा है। Settlement design का सबसे सही अंतर क्या है?", [["RTGS settles eligible transfers individually in real time, while NEFT processes transfers in batches", "RTGS पात्र transfers को real time में अलग-अलग settle करता है, जबकि NEFT transfers को batches में process करता है"], ["NEFT is a card payment and RTGS is a digital wallet", "NEFT card payment है और RTGS digital wallet"], ["RTGS requires sharing an OTP with the recipient", "RTGS में recipient के साथ OTP साझा करना आवश्यक है"], ["Both are paper-only cheque-clearing methods", "दोनों केवल paper cheque-clearing तरीके हैं"]], 0, "RTGS is real-time gross settlement; NEFT uses deferred net settlement in half-hourly batches under the current system.", "RTGS real-time gross settlement है; वर्तमान व्यवस्था में NEFT आधे घंटे के batches में deferred net settlement उपयोग करता है।", "Expected Practice"),
        q("digital-finance", "Hard", "A merchant accepts a card through a tokenized mobile wallet. What is the security purpose of using a payment token instead of exposing the card number to the merchant?", "Merchant tokenized mobile wallet से card स्वीकार करता है। Merchant को card number दिखाने के बजाय payment token का सुरक्षा उद्देश्य क्या है?", [["Reduce exposure of the actual card number during the payment", "भुगतान के दौरान वास्तविक card number का खुलासा घटाना"], ["Replace the need to authorize any purchase", "किसी भी खरीद को authorize करने की आवश्यकता हटाना"], ["Guarantee that the merchant cannot make a mistake", "गारंटी देना कि merchant गलती नहीं कर सकता"], ["Make the card PIN public to the payment network", "Card PIN को payment network के लिए सार्वजनिक करना"]], 0, "A token substitutes a limited-use payment identifier for the underlying card credentials, reducing their exposure.", "Token underlying card credentials की जगह सीमित उपयोग वाला payment identifier देता है और उनके खुलासे को घटाता है।", "Expected Practice"),
        q("digital-finance", "Hard", "A payment app shows a debit but the merchant says the order failed. What is the best next step before paying a second time?", "Payment app में debit दिखता है लेकिन merchant कहता है कि order विफल हुआ। दूसरी बार भुगतान करने से पहले सर्वोत्तम कदम क्या है?", [["Check transaction status and reference in the official app or with the bank, then follow the prescribed dispute process", "आधिकारिक app या bank से status और reference जाँचें, फिर निर्धारित dispute प्रक्रिया अपनाएँ"], ["Immediately pay again without checking", "बिना जाँचे तुरंत फिर भुगतान करें"], ["Share the PIN with the merchant to reverse it", "वापसी के लिए PIN merchant से साझा करें"], ["Delete the transaction notification", "Transaction notification delete करें"]], 0, "Checking the official status and using the provider's dispute path reduces duplicate-payment risk and preserves evidence.", "आधिकारिक status जाँचने और provider की dispute प्रक्रिया अपनाने से दोहरे भुगतान का जोखिम घटता है और प्रमाण सुरक्षित रहता है।", "Expected Practice"),

        q("future-skills-cybersecurity", "Moderate", "A developer wants one cloud service that provides virtual machines, storage and networking while allowing the organization to manage its own operating systems. Which model fits?", "Developer को ऐसा cloud service चाहिए जो virtual machines, storage और networking दे, जबकि संगठन अपना operating system स्वयं manage करे। कौन-सा model उपयुक्त है?", [["Infrastructure as a Service (IaaS)", "Infrastructure as a Service (IaaS)"], ["Software as a Service (SaaS) only", "केवल Software as a Service (SaaS)"], ["A standalone spreadsheet", "Standalone spreadsheet"], ["A physical mailing list", "Physical mailing list"]], 0, "IaaS supplies fundamental computing infrastructure while the customer generally manages the guest operating system and applications.", "IaaS मूल computing infrastructure देता है जबकि ग्राहक सामान्यतः guest operating system और applications manage करता है।", "Expected Practice"),
        q("future-skills-cybersecurity", "Moderate", "A smart thermostat measures room temperature and sends readings to a connected service. Which component is responsible for detecting the temperature?", "Smart thermostat कमरे का तापमान मापकर connected service को readings भेजता है। तापमान पहचानने के लिए कौन-सा component जिम्मेदार है?", [["A temperature sensor", "Temperature sensor"], ["An actuator motor only", "केवल actuator motor"], ["A cloud backup archive", "Cloud backup archive"], ["A keyboard driver", "Keyboard driver"]], 0, "A sensor measures a physical condition such as temperature and provides data for the connected system.", "Sensor तापमान जैसी भौतिक स्थिति मापता है और connected system को डेटा देता है।", "Expected Practice"),
        q("future-skills-cybersecurity", "Moderate", "A business wants multiple participants to share a synchronized transaction record where later changes are difficult to conceal. Which technology is associated with this approach?", "व्यवसाय ऐसा synchronized transaction record चाहता है जिसे कई प्रतिभागी साझा करें और बाद के बदलाव छिपाना कठिन हो। यह तरीका किस technology से जुड़ा है?", [["Blockchain or distributed ledger", "Blockchain या distributed ledger"], ["A local word-processing template", "Local word-processing template"], ["A display screen saver", "Display screen saver"], ["A single-user recycle bin", "Single-user recycle bin"]], 0, "A distributed ledger shares records across participants and uses linked, validated entries to make undetected alteration difficult.", "Distributed ledger प्रतिभागियों में records साझा करता है और linked, validated entries से बिना पता चले बदलाव कठिन बनाता है।", "Expected Practice"),
        q("future-skills-cybersecurity", "Moderate", "Why should security updates for an operating system and its applications be installed from trusted sources?", "Operating system और applications के security updates trusted sources से क्यों install करने चाहिए?", [["They can correct known vulnerabilities that attackers might exploit", "वे ज्ञात vulnerabilities ठीक कर सकते हैं जिनका हमलावर दुरुपयोग कर सकते हैं"], ["They guarantee that no future attack can occur", "वे गारंटी देते हैं कि भविष्य में कोई हमला नहीं होगा"], ["They remove the need for backups", "वे backups की आवश्यकता समाप्त करते हैं"], ["They make every downloaded file trustworthy", "वे हर downloaded file को trustworthy बनाते हैं"]], 0, "Trusted security updates patch known weaknesses, reducing exposure while not replacing other safeguards.", "Trusted security updates ज्ञात कमजोरियाँ ठीक करते हैं और जोखिम घटाते हैं, लेकिन अन्य सुरक्षा उपायों का स्थान नहीं लेते।", "Expected Practice"),
        q("future-skills-cybersecurity", "Moderate", "A user wants unique strong passwords for many accounts without memorizing each one. Which tool is designed to help?", "उपयोगकर्ता हर password याद रखे बिना कई accounts के लिए अलग और मजबूत passwords चाहता है। कौन-सा tool इसी में मदद करता है?", [["A reputable password manager protected by a strong master credential", "मजबूत master credential से सुरक्षित प्रतिष्ठित password manager"], ["The same short password on every site", "हर site पर वही छोटा password"], ["A public note containing all passwords", "सभी passwords वाला public note"], ["A browser history list", "Browser history list"]], 0, "A password manager can generate and store distinct credentials, protected by a strong master credential and device security.", "Password manager अलग credentials बना और सुरक्षित रख सकता है, जिन्हें मजबूत master credential और device सुरक्षा से बचाया जाता है।", "Expected Practice"),
        q("future-skills-cybersecurity", "Hard", "Which cryptographic operation is intended to verify that data has not changed, without providing a way to recover the original message from the digest?", "कौन-सी cryptographic प्रक्रिया digest से मूल संदेश वापस पाने का तरीका दिए बिना यह जाँचने के लिए है कि डेटा बदला नहीं?", [["A cryptographic hash", "Cryptographic hash"], ["Reversible encryption with a shared key", "Shared key से reversible encryption"], ["File compression", "File compression"], ["Character encoding", "Character encoding"]], 0, "A cryptographic hash produces a fixed-length digest for integrity checks and is designed to be one-way.", "Cryptographic hash integrity जाँच के लिए निश्चित लंबाई का digest बनाता है और इसे one-way बनाया जाता है।", "Expected Practice"),
        q("future-skills-cybersecurity", "Hard", "A database service account only needs to read one reporting table, but it currently has administrator rights across the server. Which security change best reduces potential damage?", "Database service account को केवल एक reporting table पढ़नी है, लेकिन उसे पूरे server पर administrator अधिकार हैं। संभावित नुकसान घटाने वाला सर्वोत्तम सुरक्षा बदलाव क्या है?", [["Grant only the minimum permissions needed for its task", "उसके कार्य के लिए आवश्यक न्यूनतम permissions ही दें"], ["Share the administrator password with all analysts", "Administrator password सभी analysts को दें"], ["Disable audit logging", "Audit logging बंद करें"], ["Make the database accessible to everyone", "Database सभी के लिए accessible करें"]], 0, "Least privilege limits an account's access to what its function requires, containing misuse or compromise.", "Least privilege किसी account की पहुँच उसके कार्य के लिए आवश्यक सीमा तक रखता है और दुरुपयोग या compromise का असर सीमित करता है।", "Expected Practice"),
        q("future-skills-cybersecurity", "Hard", "A service must store user passwords so that a database leak does not reveal reusable plaintext credentials. Which approach is appropriate?", "Service को user passwords इस तरह store करने हैं कि database leak होने पर reusable plaintext credentials उजागर न हों। कौन-सा तरीका उचित है?", [["Store salted, slow password hashes and verify by hashing the submitted password", "Salted, slow password hashes रखें और दिए गए password का hash बनाकर सत्यापित करें"], ["Encrypt every password with one key stored beside the database", "हर password को database के पास रखी एक key से encrypt करें"], ["Save passwords in a spreadsheet as plain text", "Passwords को spreadsheet में plain text रखें"], ["Store only the first character of each password", "हर password का केवल पहला अक्षर रखें"]], 0, "A unique salt and a deliberately slow password-hashing function make offline guessing harder without storing plaintext passwords.", "अलग salt और जानबूझकर धीमा password-hashing function plaintext password रखे बिना offline guessing कठिन बनाते हैं।", "Expected Practice")
    ];
}(window));
